// ---------------- P12 Retro: KNOCK engine (Web Audio path) ----------------
// Web Audio twin of the native KNOCK voice (P12NativeSampler.h), voiced against
// eSPi (measured A/B): the pad is band-limited like 26.04 kHz SP storage, 12-bit
// truncated, played back smoothly at unity level, no output filtering. DRIVE adds
// a hot input stage (transparent at 0). Optional SP OUT filters (FILTERS):
// OUT 1-2 four-pole 11 kHz, OUT 3-6 two-pole 14 kHz, OUT 7-8 raw. Replaces only
// the Classic crunch stage of a voice; Hi-Fi voices are untouched. Native-rate
// .sp12 buffers are already 26.04 kHz/12-bit and skip the storage stage.
let p12KnockCurves={};
function p12KnockCurve(drive){
  const key=Math.round(drive*100);
  if(p12KnockCurves[key])return p12KnockCurves[key];
  const knee=1-0.3*key/100, room=Math.max(1e-4,1-knee), n=8193, clip=new Float32Array(n);
  for(let i=0;i<n;i++){
    const x=(i/(n-1)*2-1)*4, ax=Math.abs(x);
    clip[i]=ax<=knee?x:Math.sign(x)*Math.min(1,knee+room*((ax-knee)/((ax-knee)+room)));
  }
  return (p12KnockCurves[key]=clip);
}
let p12KnockTrunc=null;
function p12KnockChain(input, fid, isNativeSP12Rate, chainNodes){
  const cfg=window.p12KnockWeb||{}, drive=Math.max(0,Math.min(1,Number(cfg.drive??0)));
  const g=Math.pow(10,15*drive/20), makeup=1/(1+0.45*(g-1)/4.62);
  const pre=ctx.createGain(); pre.gain.value=g/4;
  const clip=ctx.createWaveShaper(); clip.curve=p12KnockCurve(drive);
  const post=ctx.createGain(); post.gain.value=makeup;
  input.connect(pre); pre.connect(clip); clip.connect(post);
  chainNodes.push(pre,clip,post);
  let node=post;
  const lp=(f,q)=>{const b=ctx.createBiquadFilter();b.type='lowpass';b.frequency.value=Math.min(f,ctx.sampleRate*0.45);b.Q.value=q;chainNodes.push(b);return b;};
  if(!isNativeSP12Rate){
    if(!p12KnockTrunc){const n=65537;p12KnockTrunc=new Float32Array(n);for(let i=0;i<n;i++){const x=i/(n-1)*2-1;p12KnockTrunc[i]=Math.floor(Math.max(-1,Math.min(2047/2048,x))*2048)/2048;}}
    // 26.04 kHz storage band (pitch moves it, like the SP clock), then 12-bit words.
    const band=Math.max(2000,Math.min(SP12_SAMPLE_RATE*0.48*playbackRateFor(fid),ctx.sampleRate*0.45));
    const a=lp(band,0.5412), b=lp(band,1.3066), q=ctx.createWaveShaper(); q.curve=p12KnockTrunc; chainNodes.push(q);
    node.connect(a); a.connect(b); b.connect(q); node=q;
  }
  if(cfg.filters){
    const out=Number(state.sp12OutputChannel[fid]||((sp12SoundNumberForFid(fid)%8)+1));
    if(out<=2){const a=lp(11000,0.5412),b=lp(11000,1.3066);node.connect(a);a.connect(b);node=b;}
    else if(out<=6){const a=lp(14000,0.7071);node.connect(a);node=a;}
  }
  return node;
}

// ---------------- P12 Retro: SP-style fader panel API (p12-sp-mixer.js) ----------------
// Narrow access to per-pad Mix / Pan / Tune BF / Tune AT so the hardware-style
// 8-fader panel drives the SAME state as Mixer-32 (native sync picks it up).
// Tune BF stays export-baked and Tune AT stays post-sample, exactly as before.
if(typeof window!=='undefined') window.p12SpMixApi = Object.freeze({
  banks: BANKS.slice(),
  voices: VOICES.map(v=>v.label),
  idsForBank: b=>VOICES.map(v=>fullId(b, v.id)),
  bank: ()=>state.currentBank,
  setBank: b=>{ if(BANKS.includes(b)) setBank(b); },
  get: fid=>({ vol: Number(state.vol[fid] ?? 0.9), pan: Number(state.pan[fid] || 0),
               tune: Number(state.tune[fid] || 0), tuneBefore: Number(state.tuneBefore[fid] || 0),
               loaded: !!state.samples[fid], mute: !!state.mute[fid], nativeIndex: ALL_IDS.indexOf(fid) }),
  setVol: (fid, v)=>{ v=Math.max(0, Math.min(1, Number(v)||0)); state.vol[fid]=v; syncVolUI(fid, v*100); updateLiveVolume(fid, v); p12MarkRecoveryDirty(); },
  setPan: (fid, v)=>{ v=Math.max(-1, Math.min(1, Number(v)||0)); state.pan[fid]=v; updateLivePan(fid, v); p12MarkRecoveryDirty(); },
  setTune: (fid, st)=>{ st=Math.max(-24, Math.min(24, Math.round(Number(st)||0))); state.tune[fid]=st; updateLiveTune(fid); p12MarkRecoveryDirty(); },
  setTuneBefore: (fid, st)=>{ st=Math.max(-48, Math.min(48, Math.round(Number(st)||0))); state.tuneBefore[fid]=st; p12MarkRecoveryDirty(); },
  auditionTuneBefore: fid=>trigger(fid, undefined, 1, undefined, null, null, true),
  hit: fid=>trigger(fid, undefined, 1),
  nativeActive: ()=>!!nativeAudioEnabled,
  outputs: ()=>ALL_IDS.map(fid=>Number(state.sp12OutputChannel[fid]||((sp12SoundNumberForFid(fid)%8)+1))),
  tempo: ()=>Number(currentPatternObj().bpm || 96),
  playing: ()=>!!state.playing,
  // P12 Retro plug-in: persist the autosave snapshot into the DAW project
  // shortly after edits (never while playing; same writer as RECOVER AUTOSAVE).
  // Wave editor (p12-wave-editor.js): sample-accurate trim on the buffer that
  // actually plays, plus destructive edits routed through applySampleToPad so
  // native staging, reverse and warp invalidation behave exactly as on load.
  wave: Object.freeze({
    ensureAudio: async()=>{ await initAudio(); return ctx; },
    buffer: fid=>(state.samples[fid]&&!state.padEmpty[fid])?activeBufferFor(fid):null,
    warped: fid=>!!(state.warp[fid]&&state.warp[fid].mode==='preserve'&&state.samplesWarped[fid]),
    name: fid=>state.sampleNames[fid]||'',
    trim: fid=>Object.assign({start:0,end:1},state.sampleTrim[fid]||{}),
    setTrim: (fid,a,b)=>{
      a=Math.max(0,Math.min(1,Number(a)||0)); b=Math.max(a+1e-6,Math.min(1,Number(b)||1));
      state.sampleTrim[fid]={start:a,end:b};
      const padEl=document.getElementById('pad-'+fid);
      if(padEl){padEl.querySelector('.trimStart').value=Math.round(a*100);padEl.querySelector('.trimEnd').value=Math.round(b*100);}
      p12MarkRecoveryDirty();
    },
    reverse: fid=>!!state.reverse[fid],
    toggleReverse: fid=>{ toggleReverse(fid); nativeAudioReady.delete(fid); nativeBufferVersions.delete(fid);
      if(nativeAudioEnabled)nativeStagePad(fid).catch(()=>{}); p12MarkRecoveryDirty(); },
    replace: (fid,forwardBuf,keepTrim)=>{
      const t=Object.assign({start:0,end:1},state.sampleTrim[fid]||{}), name=state.sampleNames[fid]||'Edited';
      applySampleToPad(fid,forwardBuf,name);
      if(keepTrim)state.sampleTrim[fid]=t;
      const padEl=document.getElementById('pad-'+fid);
      if(padEl&&keepTrim){padEl.querySelector('.trimStart').value=Math.round(t.start*100);padEl.querySelector('.trimEnd').value=Math.round(t.end*100);}
      p12MarkRecoveryDirty();
    },
    createBuffer: (ch,len,rate)=>ctx.createBuffer(ch,len,rate),
    // Library sidebar (p12-library.js): load a File through the normal pad loader.
    loadFile: (fid,file)=>loadSampleFile(fid,file),
    // SP-1200 style Multi-Pitch: copy one pad's sample (trim + reverse) onto all
    // eight pads of a bank and give each pad its own Tune AT step.
    multiPitch: (src,bank,steps)=>{
      if(!state.samples[src]||state.padEmpty[src]||!BANKS.includes(bank))return false;
      const buf=state.samples[src], trim=Object.assign({start:0,end:1},state.sampleTrim[src]||{}), rev=!!state.reverse[src];
      const base=(state.sampleNames[src]||'Sample');
      // Assign all eight pads first WITHOUT native staging (that encodes the
      // PCM synchronously per pad and froze the UI ~0.6 s), then stage the
      // copies one pad at a time with a yield between, keeping the UI live.
      const nativeWas=nativeAudioEnabled, staged=[];
      nativeAudioEnabled=false;
      try{
      VOICES.forEach((v,i)=>{
        const fid=fullId(bank,v.id);
        if(fid!==src){ state.reverse[fid]=rev; applySampleToPad(fid,buf,base); staged.push(fid); }
        state.sampleTrim[fid]=Object.assign({},trim);
        const padEl=document.getElementById('pad-'+fid);
        if(padEl){padEl.querySelector('.trimStart').value=Math.round(trim.start*100);padEl.querySelector('.trimEnd').value=Math.round(trim.end*100);
          padEl.querySelector('.revbtn')?.classList.toggle('active',rev);}
        state.tune[fid]=Math.max(-24,Math.min(24,Math.round(Number(steps[i])||0)));
      });
      }finally{ nativeAudioEnabled=nativeWas; }
      if(nativeWas)(async()=>{
        for(const fid of staged){
          await new Promise(r=>setTimeout(r,0));
          if(!nativeAudioEnabled||state.samples[fid]!==buf)continue;
          try{ await nativeStagePad(fid); }catch(e){ console.warn('native pad stage',fid,e); }
        }
      })();
      p12MarkRecoveryDirty();
      return true;
    },
    hit: fid=>trigger(fid, undefined, 1)
  })
});

