let p12RecoveryBusy=false,p12RecoveryDirtyTimer=null,p12RecoveryDeferred=false;
async function p12WriteRecovery(reason='timer'){
  // Recovery serialization can be tens of MB. Never JSON-clone/write that
  // data while the sequencer or count-in is running: renderer stalls feed
  // native note events late even though the JUCE callback itself is healthy.
  if(state.playing||state.counting){p12RecoveryDeferred=true;return;}
  if(p12RecoveryBusy||state.exporting||!p12SafetyBridge||typeof p12SafetyBridge.writeRecovery!=='function')return;
  p12RecoveryBusy=true;try{const r=await p12SafetyBridge.writeRecovery({...p12RecoverySnapshot(),reason});p12RecoveryDeferred=!(r&&r.ok);p12DiagSend('RECOVERY','write',{reason,ok:!!(r&&r.ok),path:r&&r.path||''},r&&r.ok?'INFO':'WARN');}catch(e){p12DiagSend('RECOVERY','write-error',{reason,message:String(e&&e.message||e)},'ERROR');}finally{p12RecoveryBusy=false;}
}
function p12MarkRecoveryDirty(){
  p12RecoveryDeferred=true;clearTimeout(p12RecoveryDirtyTimer);
  if(state.playing||state.counting)return;
  p12RecoveryDirtyTimer=setTimeout(()=>p12WriteRecovery('idle-edit'),15000);
}
setInterval(()=>{if(!state.playing&&!state.counting&&p12RecoveryDeferred)p12WriteRecovery('idle-180s');},180000);
document.addEventListener('change',p12MarkRecoveryDirty,true);document.addEventListener('pointerup',p12MarkRecoveryDirty,true);

