let jitterWindowWasHidden=document.hidden;
document.addEventListener('visibilitychange',()=>{jitterWindowWasHidden=true;});
function p12MeasureEventLoop(){
  const now=performance.now(),drift=Math.max(0,now-jitterLast-1000);
  jitterMax=Math.max(jitterMax,drift);jitterLast=now;
  // Keep the real peak; record visibility to distinguish background delays.
  if(drift>=100)p12DiagSend('UI','event-loop-stall',{
    delayMs:+drift.toFixed(1),peakMs:+jitterMax.toFixed(1),
    hidden:document.hidden,visibilityChangedOrHidden:jitterWindowWasHidden,
    autosave:false
  },'WARN');
  jitterWindowWasHidden=document.hidden;
  const el=byId('diagJitter');
  if(el)el.textContent='UI '+drift.toFixed(1)+'ms / peak '+jitterMax.toFixed(1)+'ms (not audio underruns)';
}
setInterval(p12MeasureEventLoop,1000);
